import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = (int) nextLong();
        long[] x = new long[n], y = new long[n];
        for (int i = 0; i < n; i++) {
            x[i] = nextLong();
            y[i] = nextLong();
        }
        // Dense Prim: best[j] is the cheapest edge from j to the current tree.
        long[] best = new long[n];
        java.util.Arrays.fill(best, Long.MAX_VALUE);
        boolean[] used = new boolean[n];
        best[0] = 0;
        long total = 0;
        for (int it = 0; it < n; it++) {
            int u = -1;
            for (int i = 0; i < n; i++)
                if (!used[i] && (u < 0 || best[i] < best[u])) u = i;
            used[u] = true;
            total += best[u];
            for (int j = 0; j < n; j++)
                if (!used[j]) best[j] = Math.min(best[j], Math.abs(x[u] - x[j]) + Math.abs(y[u] - y[j]));
        }
        System.out.println(total);
    }
}

package main

import (
	"bufio"
	"fmt"
	"math"
	"os"
)

func abs(v int64) int64 {
	if v < 0 {
		return -v
	}
	return v
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int
	fmt.Fscan(in, &n)
	x := make([]int64, n)
	y := make([]int64, n)
	for i := 0; i < n; i++ {
		fmt.Fscan(in, &x[i], &y[i])
	}
	// Dense Prim: best[j] is the cheapest edge from j to the current tree.
	best := make([]int64, n)
	for i := range best {
		best[i] = math.MaxInt64
	}
	used := make([]bool, n)
	best[0] = 0
	var total int64
	for it := 0; it < n; it++ {
		u := -1
		for i := 0; i < n; i++ {
			if !used[i] && (u < 0 || best[i] < best[u]) {
				u = i
			}
		}
		used[u] = true
		total += best[u]
		for j := 0; j < n; j++ {
			if !used[j] {
				best[j] = min(best[j], abs(x[u]-x[j])+abs(y[u]-y[j]))
			}
		}
	}
	fmt.Println(total)
}
